SINA_SMART["anat3-orbital-appendages"] = {"lecture":"anat3-orbital-appendages","title":"Anatomy of the orbital appendages","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-orbital-appendages:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-orbital-appendages:s1","text":"Describe and explain: What the lecture asks you to do","topic":"What the lecture asks you to do","sec":1,"importance":"standard","highYield":"untested"},{"id":"anat3-orbital-appendages:e0","text":"Orbital contents: eyeball, extraocular muscles, fascia bulbi, nerves, ciliary ganglion, ophthalmic vessels, lacrimal gland, orbital fat.","topic":"Contents of the orbit","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e1","text":"Levator palpebrae superioris: CN III; its smooth part (superior tarsal muscle) is sympathetic.","topic":"Contents of the orbit","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e2","text":"Eyelid is 2 to 3 mm thick; the lateral, ciliary part carries the lashes.","topic":"The eyelids","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e3","text":"Five layers: skin and cilia, loose connective and adipose tissue, muscular layer, tarsal plate, palpebral conjunctiva.","topic":"The eyelids","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e4","text":"Orbital septum connects the tarsi to the orbital margins and limits the spread of infection between face and orbit.","topic":"The eyelids","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e5","text":"Glands of Zeis are sebaceous; glands of Moll are modified apocrine sweat glands.","topic":"The eyelids","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e6","text":"Conjunctival fornices are where palpebral becomes bulbar conjunctiva, enclosing the conjunctival sac.","topic":"The eyelids","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e7","text":"Tear film: oil (meibomian), water (lacrimal), mucin (goblet cells).","topic":"The tear film","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e10","text":"Lacrimal artery from the ophthalmic artery; superior ophthalmic vein to the cavernous sinus; superficial parotid nodes.","topic":"The lacrimal gland","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e8","text":"Lacrimal gland sits superolaterally in the lacrimal fossa of the frontal bone; orbital and palpebral parts; compound tubuloacinar.","topic":"The lacrimal gland","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e12","text":"Tears drain: puncta, lacrimal sac, nasolacrimal duct, inferior nasal meatus.","topic":"The flow of tears","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e9","text":"Its ducts empty into the superior conjunctival fornix.","topic":"The flow of tears","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e11","text":"Sensory: lacrimal nerve (V1). Parasympathetic: greater petrosal to pterygopalatine ganglion, stimulating secretion. Sympathetic: superior cervical ganglion via deep petrosal, inhibiting it.","topic":"Innervation of the lacrimal gland","sec":7,"importance":"core","highYield":"untested"},{"id":"anat3-orbital-appendages:e13","text":"Ciliary ganglion: parasympathetic from CN III; branches are the short ciliary nerves.","topic":"Innervation of the lacrimal gland","sec":7,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"5hpe8e":"a","oa6b6r":"a","1wks3z9":"a","mf61f3":"a","14svosu":"a","134yjbn":"a","1u1knn8":"a","15ixt2a":"a","1w10bsj":"a","439j01":"a","1syl9o6":"a","5v9jyf":"a","pp0vuz":"a","ovm7w7":"a","1vq9kmn":"a","frie1v":"a","1y5jmlh":"a","18istpx":"a","fqr60h":"a","1w3nlgk":"a","ps7d9y":"a","1rgvxpi":"a","1w70eng":"a","1bh8mq9":"a"},"mapCounts":{"verified":0,"auto":24,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-orbital-appendages:s0":{"s":0,"u":["The eyeball is the star of the orbit, but it cannot work alone.","This lecture is about everything around it: the eyelids that protect and clean it, the tear film that keeps it wet, the lacrimal gland that makes the tears, and the nerves that turn that gland on and off."],"dp":[{"h":"Basal versus reflex tears","t":"The main lacrimal gland in the superotemporal orbit makes the reflex tears, the ones that come with onions or grief. The steady, background wetting of the eye comes largely from accessory lacrimal glands, the glands of Krause in the conjunctival fornix and the glands of Wolfring at the border of the tarsal plate. It explains why an eye can still feel dry even with a healthy main gland. Source: Brainscape, Physiology of the eyelids."}]},"anat3-orbital-appendages:s1":{"s":1,"u":["Discuss the attachments of two extraocular muscles.","Discuss the formation and function of the eyelids."],"dp":[]},"anat3-orbital-appendages:e0":{"s":2,"u":["Orbital contents: eyeball, extraocular muscles, fascia bulbi, nerves, ciliary ganglion, ophthalmic vessels, lacrimal gland, orbital fat.","The eyeball , the most essential content Extraocular muscles Fascia bulbi Nerves: optic, oculomotor, trochlear, abducens, ophthalmic The ciliary ganglion The ophthalmic artery and the ophthalmic veins The lacrimal gland Orbital fat The levator palpebrae superioris raises the upper eyelid and is supplied by the oculomotor nerve."],"dp":[]},"anat3-orbital-appendages:e1":{"s":2,"u":["Levator palpebrae superioris: CN III; its smooth part (superior tarsal muscle) is sympathetic.","Its deeper smooth muscle part, the superior tarsal muscle, is supplied by sympathetic fibres.","The eyeball , the most essential content Extraocular muscles Fascia bulbi Nerves: optic, oculomotor, trochlear, abducens, ophthalmic The ciliary ganglion The ophthalmic artery and the ophthalmic veins The lacrimal gland Orbital fat The levator palpebrae superioris raises the upper eyelid and is supplied by the oculomotor nerve."],"dp":[{"h":"Why Horner's syndrome gives a drooping eyelid","t":"Two muscles lift the upper lid. The levator palpebrae superioris is skeletal muscle on CN III and does most of the work. Behind it sits the superior tarsal muscle (Muller's muscle), smooth muscle running from the underside of the levator to the upper border of the tarsus, supplied by sympathetic fibres and worth about 1 to 3 mm of lift. Lose the sympathetic supply, as in Horner's syndrome, and you get a mild ptosis, while a CN III palsy gives a far more dramatic one. Sources: Brainscape, Orbit and ocular adnexae, eyelids; Brainscape, Boards prep ocular anatomy."},{"h":"Note","t":"Levator palpebrae superioris = CN III ; its smooth deep part, the superior tarsal (Müller's) muscle = sympathetic . Closing the eye = orbicularis oculi = CN VII ."},{"h":"Clinical","t":"Ptosis : complete ptosis → CN III palsy (levator); mild ptosis with a small pupil → Horner syndrome (loss of sympathetic tarsal muscle). The orbital septum separates preseptal (lid) from orbital cellulitis."}]},"anat3-orbital-appendages:e2":{"s":3,"u":["Eyelid is 2 to 3 mm thick; the lateral, ciliary part carries the lashes.","The eyelid is 2 to 3 mm thick and has a medial part and a lateral part.","The lateral part carries the eyelashes and is known as the ciliary part ."],"dp":[]},"anat3-orbital-appendages:e3":{"s":3,"u":["Five layers: skin and cilia, loose connective and adipose tissue, muscular layer, tarsal plate, palpebral conjunctiva.","4: Layer = Tarsal plate; Note = Superior and inferior tarsi: dense connective tissue giving the lid its shape.","2: Layer = Loose connective tissue and adipose tissue; Note = Contains the sebaceous glands of Zeis and the ciliary glands of Moll, modified apocrine sweat glands, contributing sebum to the lipid film across the anterior chamber."],"dp":[{"h":"Note","t":"Eyelid layers (5) from outside in: skin and cilia → loose connective/adipose tissue → muscle (orbicularis oculi, levator) → tarsal plate → palpebral conjunctiva."}]},"anat3-orbital-appendages:e4":{"s":3,"u":["Orbital septum connects the tarsi to the orbital margins and limits the spread of infection between face and orbit.","A fibrous membrane that connects the tarsi to the margins of the orbit, bounds the orbital fat anteriorly, and helps limit the spread of infections between the face and the orbit."],"dp":[]},"anat3-orbital-appendages:e5":{"s":3,"u":["Glands of Zeis are sebaceous; glands of Moll are modified apocrine sweat glands.","2: Layer = Loose connective tissue and adipose tissue; Note = Contains the sebaceous glands of Zeis and the ciliary glands of Moll, modified apocrine sweat glands, contributing sebum to the lipid film across the anterior chamber."],"dp":[{"h":"Which gland is blocked: a stye or a chalazion","t":"The eyelid glands have names because they get blocked. The meibomian glands sit inside the tarsal plate and make the oil layer, so a blocked one gives a firm lump in the lid. The glands of Zeis are sebaceous glands at the base of each lash, and the glands of Moll are apocrine sweat glands next to them, so a blocked one gives a tender swelling right at the lid margin. Sources: Duke histology, Histology of the eye and eyelid; Brainscape, Eye and eyelid."},{"h":"Note","t":"Glands of Zeis = sebaceous ; glands of Moll = modified apocrine sweat glands ; meibomian (tarsal) glands make the oil layer. Don't swap them."}]},"anat3-orbital-appendages:e6":{"s":3,"u":["Conjunctival fornices are where palpebral becomes bulbar conjunctiva, enclosing the conjunctival sac.","The palpebral conjunctiva reflects at the superior and inferior conjunctival fornices onto the eyeball as the bulbar conjunctiva, enclosing the conjunctival sac ."],"dp":[]},"anat3-orbital-appendages:e7":{"s":4,"u":["Tear film: oil (meibomian), water (lacrimal), mucin (goblet cells).","Mucin: Source = Goblet cells of the conjunctiva; Function = Attaches the tear film to the eye, spreads the water evenly.","Oil: Source = Meibomian glands; Function = Prevents evaporation."],"dp":[{"h":"Why the tear film has to be three layers","t":"Water alone would neither stick to the cornea nor stay there. The mucin layer from the goblet cells makes the corneal surface wettable so the water spreads instead of beading, and the oil layer from the meibomian glands caps it so it does not evaporate between blinks. Lose either outer layer and the eye is dry even if tear production is normal. Sources: Duke histology, Histology of the eye and eyelid; lecture slides."},{"h":"Note","t":"Tear film, 3 layers : oil ( meibomian glands) → water ( lacrimal gland) → mucin (conjunctival goblet cells )."}]},"anat3-orbital-appendages:e10":{"s":5,"u":["Lacrimal artery from the ophthalmic artery; superior ophthalmic vein to the cavernous sinus; superficial parotid nodes.","Venous: Superior ophthalmic vein, emptying into the cavernous sinus.","Arterial: Lacrimal artery, from the ophthalmic artery, a branch of the internal carotid."],"dp":[]},"anat3-orbital-appendages:e8":{"s":5,"u":["Lacrimal gland sits superolaterally in the lacrimal fossa of the frontal bone; orbital and palpebral parts; compound tubuloacinar.","Anteriorly in the superolateral aspect of the orbit, within the lacrimal fossa, a depression in the orbital plate of the frontal bone.","It is a compound tubuloacinar gland of lobules formed by multiple acini."],"dp":[]},"anat3-orbital-appendages:e12":{"s":6,"u":["Tears drain: puncta, lacrimal sac, nasolacrimal duct, inferior nasal meatus.","It drains down the nasolacrimal duct to the inferior nasal meatus.","It passes into the lacrimal sac."],"dp":[{"h":"Note","t":"Tear drainage : lacrimal gland → superior conjunctival fornix → across the cornea → puncta → canaliculi → lacrimal sac → nasolacrimal duct → inferior meatus ."}]},"anat3-orbital-appendages:e9":{"s":6,"u":["Its ducts empty into the superior conjunctival fornix.","The gland secretes fluid into the superior conjunctival fornix.","The fluid enters the conjunctival sac."],"dp":[]},"anat3-orbital-appendages:e11":{"s":7,"u":["Sensory: lacrimal nerve (V1). Parasympathetic: greater petrosal to pterygopalatine ganglion, stimulating secretion. Sympathetic: superior cervical ganglion via deep petrosal, inhibiting it.","Parasympathetic: Pathway = Preganglionic fibres in the greater petrosal nerve (from the facial nerve), then the nerve of the pterygoid canal, synapsing in the pterygopalatine ganglion.","Sympathetic: Pathway = Fibres from the superior cervical ganglion, carried by the internal carotid plexus and the deep petrosal nerve, joining the parasympathetic fibres in the nerve of the pterygoid canal and following the same route; Effect = Inhibits fluid secretion."],"dp":[{"h":"Note","t":"Lacrimal gland nerves : secretomotor parasympathetic = CN VII → greater petrosal → nerve of pterygoid canal → pterygopalatine ganglion → V2 → zygomatic → lacrimal nerve. Sympathetic (deep petrosal) inhibits . Sensory = lacrimal nerve (V1)."},{"h":"Note","t":"The lacrimal nerve (V1) is sensory ; it only hitchhikes the parasympathetic fibres at the end. The parasympathetics come from CN VII , not V."},{"h":"Clinical","t":"A lesion of CN VII before the greater petrosal branch (at or above the geniculate ganglion) gives a dry eye as well as facial palsy; a lesion at the stylomastoid foramen does not."}]},"anat3-orbital-appendages:e13":{"s":7,"u":["Ciliary ganglion: parasympathetic from CN III; branches are the short ciliary nerves.","Its branches are the short ciliary nerves .","A peripheral parasympathetic ganglion relaying parasympathetic impulses from the oculomotor nerve to their targets."],"dp":[{"h":"Note","t":"The ciliary ganglion is a parasympathetic ganglion for CN III (pupil and ciliary muscle), not for the lacrimal gland. Lacrimal secretion relays in the pterygopalatine ganglion."}]}},"meta":{"5hpe8e":{"a":"recall","vg":"anat3-orbital-appendages:e0/recall/1"},"oa6b6r":{"a":"recall","vg":"anat3-orbital-appendages:e1/recall/1"},"1wks3z9":{"a":"recall","vg":"anat3-orbital-appendages:e2/recall/1"},"mf61f3":{"a":"recall","vg":"anat3-orbital-appendages:e2/recall/2"},"14svosu":{"a":"recall","vg":"anat3-orbital-appendages:e4/recall/1"},"134yjbn":{"a":"recall","vg":"anat3-orbital-appendages:e5/recall/1"},"1u1knn8":{"a":"recall","vg":"anat3-orbital-appendages:e3/recall/1"},"15ixt2a":{"a":"recall","vg":"anat3-orbital-appendages:e6/recall/1"},"1w10bsj":{"a":"recall","vg":"anat3-orbital-appendages:e7/recall/1"},"439j01":{"a":"recall","vg":"anat3-orbital-appendages:e7/recall/2"},"1syl9o6":{"a":"recall","vg":"anat3-orbital-appendages:e7/recall/3"},"5v9jyf":{"a":"recall","vg":"anat3-orbital-appendages:e8/recall/1"},"pp0vuz":{"a":"recall","vg":"anat3-orbital-appendages:e9/recall/1"},"ovm7w7":{"a":"recall","vg":"anat3-orbital-appendages:e2/recall/3"},"1vq9kmn":{"a":"recall","vg":"anat3-orbital-appendages:e10/recall/1"},"frie1v":{"a":"recall","vg":"anat3-orbital-appendages:e10/recall/2"},"1y5jmlh":{"a":"recall","vg":"anat3-orbital-appendages:e11/recall/1"},"18istpx":{"a":"recall","vg":"anat3-orbital-appendages:e11/recall/2"},"fqr60h":{"a":"recall","vg":"anat3-orbital-appendages:e11/recall/3"},"1w3nlgk":{"a":"recall","vg":"anat3-orbital-appendages:e13/recall/1"},"ps7d9y":{"a":"recall","vg":"anat3-orbital-appendages:e7/recall/4"},"1rgvxpi":{"a":"recall","vg":"anat3-orbital-appendages:e3/recall/2"},"1w70eng":{"a":"recall","vg":"anat3-orbital-appendages:e5/recall/1"},"1bh8mq9":{"a":"recall","vg":"anat3-orbital-appendages:e2/recall/3"}},"explRev":"692eaabf3a25"};
